local BisqueStandMaker = {}
local PRODUCTS = {
    iron_bisque_stand = { name = "Železno stojalo za žganje keramike", ironCost = 3, woodCost = 3, leatherCost = 1, time = 5, cost = 160, prestige = 3, happiness = 2, description = "Železno stojalo za žganje keramike v peči." },
    bronze_bisque_stand = { name = "Bronasto stojalo za žganje keramike", bronzeCost = 3, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 390, prestige = 5, happiness = 3, description = "Bronasto stojalo za stabilno žganje." },
    silver_bisque_stand = { name = "Srebrno stojalo za žganje keramike", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 940, prestige = 10, happiness = 4, description = "Srebrno stojalo za plemiške peči." },
    gilded_bisque_stand = { name = "Pozlačeno stojalo za žganje keramike", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 2030, prestige = 19, happiness = 5, description = "Pozlačeno stojalo za dvorne peči." },
    jewel_set_bisque_stand = { name = "Draguljasto stojalo za žganje keramike", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4380, prestige = 35, happiness = 7, description = "Draguljasto stojalo za kraljevske peči." },
    royal_sovereign_bisque_stand = { name = "Kraljevski suvereno stojalo za žganje keramike", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 9400, prestige = 67, happiness = 13, description = "Suvereno stojalo z biseri za krono." },
}
local BUILDINGS = {
    bisquestand_workshop = { name = "Stojalna delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bisquestand_house = { name = "Stojalna hiša", cost = { gold = 1185, wood = 365, stone = 270, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bisquestand_atelier = { name = "Mojstrski stojalni atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bisquestand_palace = { name = "Suverena stojalna palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BisqueStandMaker.ironStock = 14; BisqueStandMaker.bronzeStock = 12; BisqueStandMaker.woodStock = 16; BisqueStandMaker.leatherStock = 8; BisqueStandMaker.silverStock = 8; BisqueStandMaker.goldStock = 6; BisqueStandMaker.jewelStock = 4; BisqueStandMaker.pearlStock = 4
BisqueStandMaker.productStock = {}; BisqueStandMaker.buildings = {}; BisqueStandMaker.maker = nil; BisqueStandMaker.activeMaking = {}; BisqueStandMaker.totalProducts = 0; BisqueStandMaker.dayTimer = 0
function BisqueStandMaker.init() BisqueStandMaker.ironStock=14; BisqueStandMaker.bronzeStock=12; BisqueStandMaker.woodStock=16; BisqueStandMaker.leatherStock=8; BisqueStandMaker.silverStock=8; BisqueStandMaker.goldStock=6; BisqueStandMaker.jewelStock=4; BisqueStandMaker.pearlStock=4; BisqueStandMaker.productStock={}; BisqueStandMaker.buildings={}; BisqueStandMaker.maker=nil; BisqueStandMaker.activeMaking={}; BisqueStandMaker.totalProducts=0; BisqueStandMaker.dayTimer=0; print("[BisqueStandMaker] Royal Bisque Stand Maker System initialized (6 products, 4 buildings)") end
function BisqueStandMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BisqueStandMaker.maker={name=n or ("Stojalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalar najet: %s (spretnost: %d)",BisqueStandMaker.maker.name,s),"success") end; return true end
function BisqueStandMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BisqueStandMaker.build(id) local ok,e=BisqueStandMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BisqueStandMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BisqueStandMaker.getQualityBonus() local b=0; for _,bd in ipairs(BisqueStandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BisqueStandMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BisqueStandMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BisqueStandMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BisqueStandMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BisqueStandMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BisqueStandMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BisqueStandMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BisqueStandMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BisqueStandMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BisqueStandMaker.buildings==0 then return false,"Potrebna stojalna delavnica" end; if not BisqueStandMaker.maker then return false,"Potreben stojalar" end; return true end
function BisqueStandMaker.make(pt,qty) qty=qty or 1; local ok,e=BisqueStandMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BisqueStandMaker.ironStock=BisqueStandMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BisqueStandMaker.bronzeStock=BisqueStandMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BisqueStandMaker.woodStock=BisqueStandMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BisqueStandMaker.leatherStock=BisqueStandMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BisqueStandMaker.silverStock=BisqueStandMaker.silverStock-d.silverCost*qty end; if d.goldCost then BisqueStandMaker.goldStock=BisqueStandMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BisqueStandMaker.jewelStock=BisqueStandMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BisqueStandMaker.pearlStock=BisqueStandMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BisqueStandMaker.maker then t=math.max(1,t-math.floor(BisqueStandMaker.maker.skill/13)) end; table.insert(BisqueStandMaker.activeMaking,{id="bisquestand_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BisqueStandMaker.completeMaking(m) local q=1.0+(BisqueStandMaker.getQualityBonus()/100); if BisqueStandMaker.maker then q=q+(BisqueStandMaker.maker.skill/140) end; q=math.min(2.5,q); BisqueStandMaker.productStock[m.productType]=(BisqueStandMaker.productStock[m.productType] or 0)+m.quantity; BisqueStandMaker.totalProducts=BisqueStandMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BisqueStandMaker.maker then BisqueStandMaker.maker.itemsMade=BisqueStandMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BisqueStandMaker.maker.skill=math.min(100,BisqueStandMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bisquestand.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BisqueStandMaker.update(dt) if not _G.state then return end; BisqueStandMaker.dayTimer=BisqueStandMaker.dayTimer+dt; if BisqueStandMaker.dayTimer>=30 then BisqueStandMaker.dayTimer=0; for i=#BisqueStandMaker.activeMaking,1,-1 do local m=BisqueStandMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BisqueStandMaker.completeMaking(m); table.remove(BisqueStandMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BisqueStandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BisqueStandMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BisqueStandMaker.getStats() return {ironStock=BisqueStandMaker.ironStock,bronzeStock=BisqueStandMaker.bronzeStock,woodStock=BisqueStandMaker.woodStock,leatherStock=BisqueStandMaker.leatherStock,silverStock=BisqueStandMaker.silverStock,goldStock=BisqueStandMaker.goldStock,jewelStock=BisqueStandMaker.jewelStock,pearlStock=BisqueStandMaker.pearlStock,productStock=BisqueStandMaker.productStock,numBuildings=#BisqueStandMaker.buildings,hasMaker=BisqueStandMaker.maker~=nil,makerName=BisqueStandMaker.maker and BisqueStandMaker.maker.name or "—",makerSkill=BisqueStandMaker.maker and BisqueStandMaker.maker.skill or 0,activeMaking=#BisqueStandMaker.activeMaking,totalProducts=BisqueStandMaker.totalProducts} end
return BisqueStandMaker
